import string

# Define the characters to use for generating passwords
characters = string.ascii_letters + string.digits

# Function to generate a hash for a given password
def generate_hash(password):
    return hashlib.md5(password.encode()).hexdigest()

# Function to generate a rainbow table
def generate_rainbow_table(max_length):
    rainbow_table = {}
    for length in range(1, max_length + 1):
        for password in itertools.product(characters, repeat=length):
            password_str = ''.join(password)
            hash_value = generate_hash(password_str)
            rainbow_table[hash_value] = password_str
    return rainbow_table

